//! 从 `scl-gui` 的矢量图标集中挑选出来的一组常用图标。
//!
//! 原组件库把图标保存为 SVG 路径字符串，并通过 Piet 的 `BezPath` 绘制。
//! Iced 的 `svg` 组件需要完整的 SVG 文档，所以这里把路径包装成 SVG，
//! 再用 `svg::Style::color` 做主题着色。

use iced::Color;
use iced::widget::svg;

use crate::theme::Theme;

/// 一个矢量图标。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Icon {
    /// 图标名。
    pub name: &'static str,
    /// SVG viewBox 的边长。
    pub view_box: u16,
    /// SVG 路径数据。
    pub path: &'static str,
}

impl Icon {
    /// 生成 Iced 使用的 SVG 句柄。
    pub fn handle(self) -> svg::Handle {
        if self.path.is_empty() {
            return svg::Handle::from_memory(Vec::new());
        }

        let document = format!(
            r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {vb} {vb}"><path fill="#000000" d="{path}"/></svg>"##,
            vb = self.view_box,
            path = self.path
        );

        svg::Handle::from_memory(document.into_bytes())
    }

    /// 根据主题生成一个带颜色的 SVG 组件。
    pub fn view<'a>(self, _theme: &Theme, size: f32, color: Color) -> svg::Svg<'a> {
        svg::Svg::new(self.handle())
            .width(iced::Length::Fixed(size))
            .height(iced::Length::Fixed(size))
            .style(move |_, _| svg::Style { color: Some(color) })
    }
}

macro_rules! icons {
    ($($name:ident = $view_box:literal, $path:literal;)*) => {
        $(
            #[doc = concat!("内置图标 `", stringify!($name), "`。")]
            pub const $name: Icon = Icon {
                name: stringify!($name),
                view_box: $view_box,
                path: $path,
            };
        )*
    };
}

